// SOL-ExecBench #38: per-head RMSNorm of Q and K, fp32, [B, S, 48, 128].
// One fused one-shot launch. CTA = 256 threads = 16 half-warps; half-warp h owns head (hg*16 + h) and
// processes T consecutive tokens of that head (rows t*48 + head). Each lane holds 8 contiguous floats of a row
// (one 256-bit access on sm_100). All T row loads are issued before the first reduction; the weight slice
// (8 floats per lane) is loaded once and reused for the T rows.
// Grid: 2 streams x n_tb token blocks x 3 head groups. T is chosen on the host from the shape only.

#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <stdint.h>

namespace {

constexpr int D = 128;
constexpr int H = 48;
constexpr int HG = 3;          // head groups of 16 heads
constexpr int THREADS = 256;   // 16 half-warps

__device__ __forceinline__ void ld8(const float* p, float (&v)[8]) {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 1000)
    asm volatile("ld.global.L1::no_allocate.v8.f32 {%0,%1,%2,%3,%4,%5,%6,%7}, [%8];"
                 : "=f"(v[0]), "=f"(v[1]), "=f"(v[2]), "=f"(v[3]),
                   "=f"(v[4]), "=f"(v[5]), "=f"(v[6]), "=f"(v[7])
                 : "l"(p));
#else
    const float4 a = __ldg(reinterpret_cast<const float4*>(p));
    const float4 b = __ldg(reinterpret_cast<const float4*>(p) + 1);
    v[0] = a.x; v[1] = a.y; v[2] = a.z; v[3] = a.w;
    v[4] = b.x; v[5] = b.y; v[6] = b.z; v[7] = b.w;
#endif
}

__device__ __forceinline__ void st8(float* p, const float (&v)[8]) {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 1000)
    asm volatile("st.global.v8.f32 [%0], {%1,%2,%3,%4,%5,%6,%7,%8};"
                 :: "l"(p), "f"(v[0]), "f"(v[1]), "f"(v[2]), "f"(v[3]),
                    "f"(v[4]), "f"(v[5]), "f"(v[6]), "f"(v[7])
                 : "memory");
#else
    float4* q = reinterpret_cast<float4*>(p);
    q[0] = make_float4(v[0], v[1], v[2], v[3]);
    q[1] = make_float4(v[4], v[5], v[6], v[7]);
#endif
}

template <int T, int MINB>
__global__ void __launch_bounds__(THREADS, MINB)
qk_rms_tok(const float* __restrict__ q, const float* __restrict__ k,
           const float* __restrict__ wq, const float* __restrict__ wk,
           float* __restrict__ qo, float* __restrict__ ko,
           int n_tok, int n_tb, float eps)
{
    const int units = n_tb * HG;              // CTAs per stream
    int idx = blockIdx.x;
    const bool is_k = idx >= units;
    if (is_k) idx -= units;
    const int tb = idx / HG;
    const int hg = idx - tb * HG;

    const float* __restrict__ x = is_k ? k : q;
    const float* __restrict__ w = is_k ? wk : wq;
    float* __restrict__ y = is_k ? ko : qo;

    const int tid = threadIdx.x;
    const int head = hg * 16 + (tid >> 4);
    const int col = (tid & 15) * 8;
    const int t0 = tb * T;

    // 1) issue all row loads of this thread
    float v[T][8];
#pragma unroll
    for (int j = 0; j < T; ++j) {
        const int t = t0 + j;                 // uniform across the CTA
        if (T == 1 || t < n_tok) {
            ld8(x + ((size_t)t * H + head) * D + col, v[j]);
        } else {
#pragma unroll
            for (int i = 0; i < 8; ++i) v[j][i] = 0.0f;
        }
    }

    // 2) weights for this head slice (L1/L2 hits after first touch), shared by the T rows
    float wv[8];
    {
        const float4 a = __ldg(reinterpret_cast<const float4*>(w + head * D + col));
        const float4 b = __ldg(reinterpret_cast<const float4*>(w + head * D + col) + 1);
        wv[0] = a.x; wv[1] = a.y; wv[2] = a.z; wv[3] = a.w;
        wv[4] = b.x; wv[5] = b.y; wv[6] = b.z; wv[7] = b.w;
    }

    // 3) per-row reduction over the half-warp, scale, store
#pragma unroll
    for (int j = 0; j < T; ++j) {
        float ss = 0.0f;
#pragma unroll
        for (int i = 0; i < 8; ++i) ss = fmaf(v[j][i], v[j][i], ss);
        // xor offsets < 16 stay inside the half-warp; all 32 lanes are active (branches above are CTA-uniform)
        ss += __shfl_xor_sync(0xffffffffu, ss, 8);
        ss += __shfl_xor_sync(0xffffffffu, ss, 4);
        ss += __shfl_xor_sync(0xffffffffu, ss, 2);
        ss += __shfl_xor_sync(0xffffffffu, ss, 1);
        const float r = rsqrtf(ss * (1.0f / 128.0f) + eps);
        const int t = t0 + j;
        if (T == 1 || t < n_tok) {
            float o[8];
#pragma unroll
            for (int i = 0; i < 8; ++i) o[i] = (v[j][i] * r) * wv[i];
            st8(y + ((size_t)t * H + head) * D + col, o);
        }
    }
}

template <int T, int MINB>
void launch(const torch::Tensor& query, const torch::Tensor& key,
            const torch::Tensor& weight_q, const torch::Tensor& weight_k,
            torch::Tensor& query_norm, torch::Tensor& key_norm,
            int n_tok, float eps, cudaStream_t stream)
{
    const int n_tb = (n_tok + T - 1) / T;
    const int grid = 2 * HG * n_tb;
    if (grid == 0) return;
    qk_rms_tok<T, MINB><<<grid, THREADS, 0, stream>>>(
        query.data_ptr<float>(), key.data_ptr<float>(),
        weight_q.data_ptr<float>(), weight_k.data_ptr<float>(),
        query_norm.data_ptr<float>(), key_norm.data_ptr<float>(),
        n_tok, n_tb, eps);
}

}  // namespace

void run(torch::Tensor query, torch::Tensor key, torch::Tensor weight_q, torch::Tensor weight_k,
         double eps, torch::Tensor query_norm, torch::Tensor key_norm)
{
    TORCH_CHECK(query.is_cuda() && key.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(query.scalar_type() == torch::kFloat32 && key.scalar_type() == torch::kFloat32, "fp32 only");
    TORCH_CHECK(query.is_contiguous() && key.is_contiguous() && query_norm.is_contiguous() &&
                key_norm.is_contiguous() && weight_q.is_contiguous() && weight_k.is_contiguous(),
                "contiguous tensors required");
    TORCH_CHECK(query.numel() == key.numel() && query.numel() % (H * D) == 0, "shape [B,S,48,128] expected");
    TORCH_CHECK(weight_q.numel() == H * D && weight_k.numel() == H * D, "weights [48,128] expected");
    const uintptr_t align_or =
        reinterpret_cast<uintptr_t>(query.data_ptr()) | reinterpret_cast<uintptr_t>(key.data_ptr()) |
        reinterpret_cast<uintptr_t>(query_norm.data_ptr()) | reinterpret_cast<uintptr_t>(key_norm.data_ptr()) |
        reinterpret_cast<uintptr_t>(weight_q.data_ptr()) | reinterpret_cast<uintptr_t>(weight_k.data_ptr());
    TORCH_CHECK((align_or & 31u) == 0, "32-byte alignment required");

    const int64_t n_tok64 = query.numel() / (H * D);
    TORCH_CHECK(n_tok64 < (1LL << 30), "too many tokens");
    const int n_tok = static_cast<int>(n_tok64);
    const float feps = static_cast<float>(eps);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    // shape-only dispatch: S band keeps the parent's 16-row CTA; M/L block 2 or 4 tokens per thread
    if (n_tok <= 600) {
        launch<1, 8>(query, key, weight_q, weight_k, query_norm, key_norm, n_tok, feps, stream);
    } else if (n_tok <= 2100) {
        launch<2, 6>(query, key, weight_q, weight_k, query_norm, key_norm, n_tok, feps, stream);
    } else {
        launch<4, 4>(query, key, weight_q, weight_k, query_norm, key_norm, n_tok, feps, stream);
    }
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("run", &run, "flux multi-head RMSNorm QK (fp32, DPS)");
}
